mod inventory;

use inventory::available_stock;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let stock: i64 = lines.next().unwrap().parse().unwrap();
    let demand: i64 = lines.next().unwrap().parse().unwrap();
    let available = available_stock(stock);
    let fulfilled = demand.min(available);
    let backorder = demand - fulfilled;
    let remaining = available - fulfilled;
    println!("fulfilled={fulfilled}|backorder={backorder}|remaining={remaining}");
}

