mod report_rules;

use report_rules::format_entry;
use std::fs;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.split_terminator('\n');
    let title = lines.next().unwrap_or("");
    let count: usize = lines.next().unwrap_or("0").parse().unwrap();
    let entries: Vec<&str> = (0..count).map(|_| lines.next().unwrap_or("")).collect();
    let mut contents = format!("{title}\n");
    for (offset, entry) in entries.iter().enumerate() {
        contents.push_str(&format_entry(offset + 1, entry));
        contents.push('\n');
    }
    fs::write("filtered_report.txt", contents).unwrap();
    let characters: usize = entries.iter().map(|entry| entry.chars().count()).sum();
    println!("saved={}|characters={characters}", entries.len());
}

rust.report_rules.rs:
pub fn format_entry(index: usize, entry: &str) -> String {
    format!("{index}|{entry}")
}
